export const EXPORT_STYLE = ":root {\n  color-scheme: light;\n}\n* {\n  box-sizing: border-box;\n}\nbody {\n  margin: 0;\n  background: #f6f7f2;\n  color: #22342a;\n  font-family:\n    system-ui,\n    -apple-system,\n    \"Segoe UI\",\n    Roboto,\n    \"Helvetica Neue\",\n    Arial,\n    \"Noto Sans\",\n    sans-serif;\n  line-height: 1.6;\n}\n.export-toolbar {\n  position: sticky;\n  top: 0;\n  z-index: 10;\n  background: #f6f7f2;\n  border-bottom: 1px solid #dde3d8;\n}\n.export-toolbar-inner {\n  max-width: 48rem;\n  margin: 0 auto;\n  padding: 0.9rem 1.25rem;\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  gap: 1rem;\n  flex-wrap: wrap;\n}\n.book-title {\n  font-size: 1.25rem;\n  margin: 0;\n}\n.export-toggles {\n  display: flex;\n  gap: 1rem;\n}\n.export-toggle {\n  display: inline-flex;\n  gap: 0.45rem;\n  align-items: center;\n  cursor: pointer;\n}\n.book {\n  max-width: 48rem;\n  margin: 0 auto 3rem;\n  padding: 0 1.25rem;\n}\n.chapter-title {\n  margin: 2.5rem 0 1.25rem;\n}\n/* Sentence blocks keep space between successive sentences. */\n.sentence-block {\n  margin: 0 0 1.25rem;\n}\n/* The original line always stays visible; exports use the size fallback. */\n.original-line {\n  margin: 0;\n  font-size: var(--original-size, 1.15rem);\n}\n/* Annotation lines hold their space even when empty and are not selectable. */\n.ipa-line,\n.translation-line {\n  margin: 0;\n  min-height: 1.4em;\n  user-select: none;\n  font-size: 0.9rem;\n}\n/* IPA uses the annotation purple; the translation keeps muted ink. */\n.ipa-line {\n  color: #6a4fa3;\n}\n.translation-line {\n  color: #3f5148;\n}\n/* Each word and transcription wrap together while retaining the word baseline. */\n.ipa-word {\n  display: inline-flex;\n  flex-direction: column;\n  align-items: center;\n  vertical-align: baseline;\n}\n/* Only the transcription hides when IPA is toggled off. */\n.ipa-word-ipa {\n  color: #6a4fa3;\n  user-select: none;\n  font-size: var(--ipa-size, 0.75rem);\n  line-height: 1.35;\n}\n/* Every original word is a lookup target; hover tint is the affordance. */\n.lookup-word,\n.ipa-word {\n  cursor: pointer;\n  border-radius: 0.2rem;\n}\n.lookup-word:hover,\n.ipa-word:hover {\n  background: #ecefe6;\n}\n.lookup-popup {\n  /* border-box keeps the rendered outer box at the shared POPUP_WIDTH_PX.\n     The app has no universal reset, so this declaration must live on the\n     element: content-box added padding and border beyond the clamp's width\n     (audit 2026-10-23). The export's universal reset covers its other elements. */\n  box-sizing: border-box;\n  position: fixed;\n  z-index: 20;\n  width: 18rem;\n  max-width: calc(100vw - 1rem);\n  max-height: 16rem;\n  overflow-y: auto;\n  background: #ffffff;\n  border: 1px solid #dde3d8;\n  border-radius: 0.5rem;\n  padding: 0.6rem 0.9rem;\n  box-shadow: 0 0.4rem 1rem rgba(34, 52, 42, 0.12);\n}\n/* The lookup card presents the word, lemma and actions on one row. */\n.lookup-head {\n  display: flex;\n  align-items: baseline;\n  gap: 0.4rem;\n  margin-bottom: 0.2rem;\n}\n.lookup-head-word {\n  font-weight: 600;\n  font-size: 1.05rem;\n}\n.lookup-lemma {\n  color: #5c6f64;\n  font-size: 0.8rem;\n}\n.lookup-head-actions {\n  margin-left: auto;\n  display: flex;\n  gap: 0.15rem;\n}\n.lookup-head-actions button {\n  border: none;\n  background: none;\n  padding: 0 0.2rem;\n  cursor: pointer;\n  font-size: 0.9rem;\n  line-height: 1.2;\n}\n.lookup-head-actions button:hover {\n  background: #ecefe6;\n  border-radius: 0.25rem;\n}\n.lookup-popup p {\n  margin: 0.15rem 0;\n}\n.lookup-ipa {\n  color: #5c6f64;\n}\n.lookup-pos {\n  color: #5c6f64;\n  font-size: 0.85rem;\n}\n/* Sense lines arrive newline-separated from ECDICT; preserve their breaks. */\n.lookup-translation {\n  white-space: pre-line;\n}\n.lookup-status {\n  color: #5c6f64;\n}\n.code-block {\n  background: #ecefe6;\n  border-radius: 0.5rem;\n  padding: 0.75rem 1rem;\n  overflow-x: auto;\n  margin: 0 0 1.25rem;\n}\n.raw-block {\n  margin: 0 0 1.25rem;\n  color: #5c6f64;\n}\n/* Illustration placeholders show captions in place of image bytes. */\n.image-block {\n  margin: 0 auto 1.25rem;\n  max-width: 60%;\n  text-align: center;\n}\n.image-placeholder {\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  min-height: 6rem;\n  background: #ecefe6;\n  border: 1px dashed #b8c4bc;\n  border-radius: 0.5rem;\n  font-size: 1.75rem;\n}\n.image-block figcaption {\n  margin-top: 0.4rem;\n  color: #5c6f64;\n  font-size: 0.85rem;\n}\n/* Display toggles hide annotations while keeping original words clickable. */\nbody.hide-ipa .ipa-line,\nbody.hide-ipa .ipa-word-ipa {\n  display: none;\n}\nbody.hide-translation .translation-line {\n  display: none;\n}\n@media (max-width: 640px) {\n  .book {\n    padding: 0 1rem;\n  }\n  .original-line {\n    font-size: 1.05rem;\n  }\n}";
